#include <iostream>
#include <string>

struct DATE {
    int day, month, year;
};

struct Sinhvien {
    std::string hoten;
    DATE ns;
    float diem;
    Sinhvien* tiep = nullptr;
};

Sinhvien* dau = nullptr;
Sinhvien* cuoi = nullptr;
int sosv = 0;

Sinhvien* taoSinhVien(const std::string& hoten, int d, int m, int y, float diem) {
    Sinhvien* kq = new Sinhvien{hoten, {d, m, y}, diem, nullptr};
    return kq;
}

void boSung(Sinhvien* cur) {
    if (sosv == 0) {
        dau = cuoi = cur;
    } else {
        cuoi->tiep = cur;
        cuoi = cur;
    }
    sosv++;
}

void xoa(int n) {
    if (n < 1 || n > sosv) return;
    if (sosv == 1 && n == 1) {
        delete dau;
        dau = cuoi = nullptr;
        sosv--;
        return;
    }
    if (n == 1) {
        Sinhvien* cur = dau;
        dau = cur->tiep;
        delete cur;
        sosv--;
        return;
    }
    Sinhvien* truoc = dau;
    for (int i = 1; i < n - 1; ++i) {
        truoc = truoc->tiep;
    }
    Sinhvien* cur = truoc->tiep;
    truoc->tiep = cur->tiep;
    if (cur == cuoi) {
        cuoi = truoc;
    }
    delete cur;
    sosv--;
}

void inDanhSach() {
    Sinhvien* cur = dau;
    int i = 1;
    while (cur != nullptr) {
        std::cout << "SV " << i << ": " << cur->hoten 
                  << " | NS: " << cur->ns.day << "/" << cur->ns.month << "/" << cur->ns.year
                  << " | Diem: " << cur->diem << "\n";
        cur = cur->tiep;
        i++;
    }
}

void giaiPhongDanhSach() {
    while (dau != nullptr) {
        Sinhvien* temp = dau;
        dau = dau->tiep;
        delete temp;
    }
    cuoi = nullptr;
    sosv = 0;
}

int main() {
    boSung(taoSinhVien("Nguyen Van A", 1, 1, 2002, 8.5f));
    boSung(taoSinhVien("Tran Thi B", 15, 5, 2002, 9.0f));
    boSung(taoSinhVien("Le Van C", 20, 11, 2001, 7.5f));

    std::cout << "Danh sach ban dau:\n";
    inDanhSach();

    std::cout << "Sau khi xoa sinh vien thu 2:\n";
    xoa(2);
    inDanhSach();

    giaiPhongDanhSach();
    return 0;
}

body.vi:
Kiểu hợp (`union`) là kiểu dữ liệu do người dùng tự định nghĩa tương tự như `struct`, nhưng với điểm khác biệt cốt lõi: tất cả các thành phần trong `union` đều chia sẻ chung một vùng nhớ (cùng địa chỉ bắt đầu).
- Cú pháp:
```cpp
union TenKieu {
    KieuDuLieu thanhPhan1;
    KieuDuLieu thanhPhan2;
    // ...
};
```
- Kích thước: Kích thước (`sizeof`) của một `union` ít nhất bằng kích thước của thành phần có kích thước lớn nhất (cộng thêm phần đệm căn chỉnh byte nếu cần).

body.en:
A `union` is a user-defined type similar to `struct`, with one crucial difference: all members of a `union` share the exact same memory storage (starting at the same memory address).
- Syntax:
```cpp
union TypeName {
    Type member1;
    Type member2;
    // ...
};
```
- Size: The size (`sizeof`) of a union is at least large enough to hold its largest member (plus any padding required for proper alignment).

example.code:
#include <iostream>

union DataUnion {
    int iVal;
    float fVal;
    char ch;
};

int main() {
    DataUnion u;

    u.iVal = 65;
    std::cout << "Kich thuoc DataUnion: " << sizeof(u) << " bytes\n";
    std::cout << "u.iVal = " << u.iVal << "\n";
    std::cout << "u.ch   = " << u.ch << "\n";

    u.fVal = 3.14159f;
    std::cout << "Sau khi gan u.fVal:\n";
    std::cout << "u.fVal = " << u.fVal << "\n";
    std::cout << "Gia tri u.iVal da bi ghi de boi bieu dien bit float.\n";

    return 0;
}
